function l(i){let o=i.trim();if(!o)return[];let c=o.split(/(?<=[.!?…])\s+|\n+/).map(n=>n.trim()).filter(Boolean),s=[];for(let n of c){if(n.length<=240){s.push(n);continue}let f=n.split(/\s+/),t="";for(let e of f){let r=t?`${t} ${e}`:e;r.length>240&&t?(s.push(t),t=e):t=r}t&&s.push(t)}return s}export{l as a};
